class DataProcessor:
    def __init__(self, data):
        self.data = data

    def clean(self):
        """Remove None values and convert strings to lowercase"""
        return [str(item).lower() if item is not None else None
                for item in self.data]

    def summarize(self):
        """Return basic statistics"""
        clean_data = [x for x in self.clean() if x is not None]
        return {
            'count': len(clean_data),
            'unique': len(set(clean_data)),
            'sample': clean_data[:3] if len(clean_data) > 3 else clean_data
        }

# Example usage
processor = DataProcessor(['Apple', None, 'banana', 'APPLE', 'orange'])
print(processor.summarize())
```

